int solution(vector<int>& arr) {
    int n = arr.size();
    if (n == 1) return arr[0];
    vector<int> dp(n + 1, 0);
    dp[1] = arr[0];
    dp[2] = arr[0] + arr[1];
    for (int i = 3; i <= n; i++) {
        dp[i] = max(dp[i - 2], dp[i - 3] + arr[i - 2]) + arr[i - 1];
    }
    return dp[n];
}

