    boolean[] vis = new boolean[n];
    int res = 0;
    for (int i = 0; i < n; i++) {
        if (vis[i]) continue;
        res++;
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        st.add(i);
        vis[i] = true;
        while (!st.isEmpty()) {
            int x = st.poll();
            for (int y : g.get(x)) if (!vis[y]) { vis[y] = true; st.add(y); }
        }
    }
    return res;
}

